/// <summary>
/// Class entry point. The system will call this method when a designated menu 
/// is selected or when execution starts and this class is set as the startup class.
/// </summary>
/// <param name = "_args">The specified arguments.</param>
public static void main(Args _args)
{
    GUPPricingAttributeLink GUPPricingAttributeLink;
    ClassId classId = classNum(METGUPPricingAttributeMETInventItemOrderSetupMTCLegacyCode);
    ttsbegin;
    update_recordset GUPPricingAttributeLink
        setting PriceAttributeClassId = classId,
                SourceName = 'METInventItemOrderSetup',
                FieldName = 'MTCLegacyCode',
                TableName = 'METInventItemOrderSetup',
                FieldPath = 'SalesLine#METInventItemOrderSetup_ItemId$ItemId#MTCLegacyCode'
        where GUPPricingAttributeLink.SourceName == 'METItemSiteSettingsSetup' && GUPPricingAttributeLink.FieldName == 'MTCLegacyCode';
    ttscommit;
    // Old field path is SalesLine#METItemSiteSettingsSetup_ItemId$ItemId#MTCLegacyCode
    info("@SYS119229");
}
